<script setup lang="ts">
import {computed,ref} from 'vue'
import EntryBuilder from '../components/compendium/EntryBuilder.vue'
import {BUILDER_CATEGORIES,builderExample} from '../../shared/entry-builder-examples'
import {applyEntryBuilder} from '../../shared/entry-builders'
import {cloneEntry,type CompendiumKind,type EntryData} from '../../shared/compendium-editing'
import '../components/compendium/entry-editor.css'
const kind=ref<CompendiumKind>('classes'),generation=ref(0),entries=ref<Partial<Record<CompendiumKind,EntryData>>>({}),notice=ref('')
const current=computed({get:()=>entries.value[kind.value]??builderExample(kind.value),set:value=>{entries.value[kind.value]=value;notice.value=''}})
function choose(value:CompendiumKind){kind.value=value;notice.value=''}
function save(){entries.value[kind.value]=applyEntryBuilder(current.value,kind.value);notice.value='Preview changes saved for this category. Your library and characters are unchanged.'}
function reset(){entries.value[kind.value]=cloneEntry(builderExample(kind.value));generation.value++;notice.value='Example restored.'}
</script>
<template><main class="builder-gallery"><header><h1 class="font-display">Compendium builders</h1><p>Try every category with an existing example. Make changes, move through its sections and review the result.</p><p class="entry-hint">These examples are separate from your library. Changes last while this page stays open.</p></header><nav class="builder-gallery-categories" aria-label="Preview categories"><button v-for="c in BUILDER_CATEGORIES" :key="c.kind" type="button" class="hw-button" :class="{'hw-button-primary':kind===c.kind}" :aria-pressed="kind===c.kind" @click="choose(c.kind)">{{c.label}}</button></nav><section class="builder-gallery-editor" :aria-label="BUILDER_CATEGORIES.find(c=>c.kind===kind)!.label+' builder'"><EntryBuilder :key="kind+':'+generation" v-model="current" :kind="kind" demo /><footer class="builder-gallery-actions"><button type="button" class="hw-button hw-button-primary" @click="save">Save preview changes</button><button type="button" class="hw-button" @click="reset">Reset this example</button><RouterLink to="/compendium" class="hw-text-button">Open my Compendium</RouterLink></footer><p v-if="notice" class="hw-callout" role="status">{{notice}}</p></section></main></template>
<style scoped>.builder-gallery{max-width:1500px;margin:auto;padding:30px 24px 70px;color:var(--cb-ink)}header{max-width:800px;margin-bottom:24px}h1{font-size:2rem;color:var(--color-gold-soft);margin-bottom:12px}p{line-height:1.6;margin-bottom:8px}.builder-gallery-categories{display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid var(--cb-line);padding-bottom:24px;margin-bottom:24px}.builder-gallery-editor{min-width:0}.builder-gallery-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:24px;padding-top:20px;border-top:1px solid var(--cb-line)}@media(max-width:650px){.builder-gallery{padding:20px 12px}.builder-gallery-categories{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.builder-gallery-categories button{font-size:.8rem;padding:9px 5px;white-space:normal;min-width:0;overflow-wrap:anywhere}h1{font-size:1.6rem}}</style>
